const evento = $json.body || $json;
const tipo = evento.type;

if (tipo === 'checkout.session.completed') {
  const session = evento.data.object;
  return [{ json: {
    accion: 'activar_inicial',
    lote_id: session.client_reference_id,
    stripe_customer_id: session.customer,
    stripe_subscription_id: session.subscription
  }}];
}

if (tipo === 'invoice.paid') {
  const invoice = evento.data.object;
  const periodEnd = invoice.lines && invoice.lines.data && invoice.lines.data[0] && invoice.lines.data[0].period ? invoice.lines.data[0].period.end : null;
  return [{ json: {
    accion: 'renovar',
    stripe_subscription_id: invoice.subscription,
    fecha_vencimiento: periodEnd ? new Date(periodEnd * 1000).toISOString() : null
  }}];
}

if (tipo === 'customer.subscription.deleted') {
  const sub = evento.data.object;
  return [{ json: {
    accion: 'cancelar',
    stripe_subscription_id: sub.id
  }}];
}

return [{ json: { accion: 'ignorar' } }];

const items = $input.all();
