const loteId = $('Normalizar Verificación Token7').item.json.loteId;
const payload = $json.body || $json;
const status = Number($json.statusCode || 200);
if ($json.error || (status !== 200 && status !== 404)) return [{json:{ httpStatus:502,error:'No se pudo consultar la conexión de redes. Intenta de nuevo.' }}];
const profiles = Array.isArray(payload.profiles) ? payload.profiles : [];
const profile = payload.profile || profiles.find(p=>p.username===loteId);
const social = profile?.social_accounts || {};
const ready = account => typeof account === 'string' ? !!account.trim() : !!(account && !account.reauth_required && (account.username || account.handle || account.id));
const plataformas = {facebook:ready(social.facebook),instagram:ready(social.instagram)};
const conectado = plataformas.facebook && plataformas.instagram;
return [{json:{conectado,parcial:!conectado && (plataformas.facebook || plataformas.instagram),plataformas}}];

const crypto = require('crypto');
const items = $input.all();
const match = items.length > 0 ? items[0].json : null;
const generarToken = () => crypto.randomBytes(16).toString('hex');
return [{ json: {
  tokenValido: !!(match && match.id),
  loteId: match ? match.id : null,
