} }];

const lead = $json;
const body = $('Webhook WhatsApp1').item.json.body;
const data = body.data || {};
const msg = data.message || {};
const isImage = !!msg.imageMessage;
const isDoc = !!msg.documentMessage;
const mimetype = isImage ? msg.imageMessage.mimetype : isDoc ? msg.documentMessage.mimetype : null;
const tiposPermitidos = new Set(['image/jpeg', 'image/png', 'image/webp', 'application/pdf']);
const ext = mimetype ? String(mimetype.split('/')[1] || '').replace(/^jpeg$/i, 'jpg').toLowerCase() : null;
const remoteJid = String(data.key?.remoteJid || '');
const phone = remoteJid.split('@')[0].replace(/:\d+$/, '').replace(/[^0-9]/g, '');
const messageId = (data.key && data.key.id) || null;
const base64 = data.base64 || null;
const loteId = String(lead.lote_id || '').trim();
const leadId = String(lead.id || '').trim();
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (!uuid.test(loteId) || !uuid.test(leadId)) throw new Error('No se pudo validar el lote y lead para guardar el documento.');

const mensajesPorStep = {
  1: 'Para agendar tu cita necesito 3 documentos rápidos. Primero, mándame una foto clara de tu identificación oficial (INE), por favor.',
  2: 'Ahora mándame tu comprobante de domicilio, en foto o PDF.',
  3: 'Por último, mándame tu comprobante de ingresos (recibo de nómina, estado de cuenta o constancia de situación fiscal).'
};
const mensajeFaltante = mensajesPorStep[lead.encuesta_step] || 'Por favor envía una foto clara o PDF del documento solicitado.';
const tipoPermitido = tiposPermitidos.has(mimetype);
const necesitaDescarga = !base64 && tipoPermitido && !!messageId;
const continuar = !!(base64 && tipoPermitido && phone);
return [{ json: {
  continuar, necesitaDescarga, lead_id: leadId, lote_id: loteId,
  step: Number(lead.encuesta_step), phone, base64, mimetype, ext,
  messageId, mensajeFaltante
} }];

const item = $json;
const buffer = Buffer.from(item.base64, 'base64');
const filename = `${item.step}_${Date.now()}.${item.ext}`;
const binary = await this.helpers.prepareBinaryData(buffer, filename, item.mimetype);
return [{ json: { ...item, filename }, binary: { data: binary } }];

const item = $('Base64 y binario1').item.json;
const mapa = {
  1: { columna: 'url_ine', siguiente: 2, mensaje: 'Perfecto, recibí tu identificación. Ahora, por favor envíame tu comprobante de domicilio en formato PDF o foto nítida.' },
  2: { columna: 'url_comprobante_domicilio', siguiente: 3, mensaje: 'Excelente, comprobante de domicilio recibido. Por último, envíame tu comprobante de ingresos (recibo de nómina, estado de cuenta o constancia de situación fiscal).' },
  3: { columna: 'url_comprobante_ingresos', siguiente: 4, mensaje: 'Listo, ya tengo tus 3 documentos. Tu expediente está completo, en breve un asesor te contactará para agendar tu cita.' }
};
const info = mapa[Number(item.step)];
if (!info) throw new Error('Paso de documentación inválido.');
const objectPath = String(item.lote_id) + '/' + String(item.lead_id) + '/' + String(item.filename);
const completo = info.siguiente > 3;
const updatePayload = { [info.columna]: objectPath, encuesta_step: info.siguiente };
if (completo) updatePayload.status = 'Documentación Completa';
return [{ json: { lead_id: item.lead_id, lote_id: item.lote_id, phone: item.phone, mensaje: info.mensaje, updatePayload } }];

const output = $('AI Agent Vendedor1').item.json.output || '';
const previo = $('Buscar Lead Existente1').item.json || {};

function extraer(regex) {
  const val = output.match(regex)?.[1]?.trim();
  if (!val || /^(pendiente|null|n\/a)$/i.test(val)) return null;
  return val;
}

return [{
  json: {
    nombre: extraer(/Nombre:\s*([^,\n\r]+)/) || previo.nombre || 'Prospecto WhatsApp',
    auto_interes: extraer(/Auto:\s*([^,\n\r]+)/) || previo.auto_interes || null,
    enganche: extraer(/Enganche:\s*([^\n\r]+)/) || previo.enganche || null,
    situacion_laboral: extraer(/Trabajo:\s*([^.\n\r]+)/) || previo.situacion_laboral || null,
    fecha_cita: extraer(/Cita:\s*([0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2})/) || previo.fecha_cita || null
  }
}];

const prev = $('Documentación de fase de validación1').item.json;
const resp = $json;
const base64 = (resp && (resp.base64 || resp.data)) || null;
return [{ json: { ...prev, base64, continuar: !!(base64 && prev.mimetype) } }];

const cita = $('Webhook Nueva Cita').item.json.body.record;
const loteRow = ($('Buscar Instancia para Nueva Cita').item.json && $('Buscar Instancia para Nueva Cita').item.json[0]) || {};
const datosLote = ($('Buscar Datos Lote para Cita').item.json && $('Buscar Datos Lote para Cita').item.json[0]) || {};
const telefonoNotificaciones = (loteRow.telefono_notificaciones || '').trim();
const instanceName = loteRow.instance_name || null;
const apiKey = loteRow.api_key || null;
const debeNotificar = !!(telefonoNotificaciones && instanceName && apiKey);
const direccion = datosLote.direccion || null;
const ciudad = datosLote.ciudad || null;
const horaAbre = datosLote.hora_abre ? datosLote.hora_abre.slice(0, 5) : null;
const horaCierra = datosLote.hora_cierra ? datosLote.hora_cierra.slice(0, 5) : null;
const diasAtencion = datosLote.dias_atencion || null;
const mensajeDueno = '📅 *Nueva cita agendada*\n\n'
  + '👤 Cliente: ' + (cita.nombre_cliente || 'Sin nombre') + '\n'
  + '📱 Teléfono: ' + (cita.telefono || 'Sin teléfono') + '\n'
  + '🚗 Auto de interés: ' + (cita.auto_interes || 'No especificado') + '\n'
  + '🗓️ Fecha: ' + (cita.fecha_cita || '---') + '\n'
  + '⏰ Hora: ' + (cita.hora_cita || '').slice(0, 5) + ' hrs';
let mensajeCliente = '✅ *¡Tu cita está confirmada, ' + (cita.nombre_cliente || 'estimado cliente') + '! 🤝*\n\n'
  + '🗓️ Fecha: *' + (cita.fecha_cita || '---') + '*\n'
  + '⏰ Hora: *' + (cita.hora_cita || '').slice(0, 5) + ' hrs*\n'
  + '🚗 Auto: *' + (cita.auto_interes || 'el vehículo de tu interés') + '*\n\n';
if (direccion) {
  mensajeCliente += '📍 *Nuestra ubicación:*\n' + direccion + (ciudad ? ', ' + ciudad : '') + '\n\n';
}
if (horaAbre && horaCierra) {
  mensajeCliente += '🕐 *Horario:* ' + horaAbre + ' a ' + horaCierra + ' hrs'
    + (diasAtencion ? '\n📆 ' + diasAtencion : '') + '\n\n';
}
mensajeCliente += '¡Te esperamos! Si necesitas cambiar o cancelar tu cita, avísanos con anticipación. 🙏';
const telefonoCliente = cita.telefono || null;
const debeConfirmarCliente = !!(telefonoCliente && instanceName && apiKey);
return [{ json: { debeNotificar, telefonoNotificaciones, instanceName, apiKey, mensaje: mensajeDueno, mensajeCliente, telefonoCliente, debeConfirmarCliente } }];

const items = $input.all();
const ahora = new Date();
const resultado = [];
for (const item of items) {
  const c = item.json;
  if (!c.fecha_cita || !c.hora_cita) continue;
  const horaLimpia = c.hora_cita.length === 5 ? c.hora_cita + ':00' : c.hora_cita;
  const citaUTC = new Date(`${c.fecha_cita}T${horaLimpia}-06:00`);
  const diffHoras = (citaUTC - ahora) / 3600000;
  if (diffHoras > 0 && diffHoras <= 3) {
    resultado.push({ json: c });
  }
}
return resultado;

const cita = $('Filtrar Citas en Ventana 3h').item.json;
const instancia = ($json && $json[0]) || {};
const mensaje = `⏰ *Recordatorio de tu cita*\n\n¡Hola ${cita.nombre_cliente || ''}! Te recordamos tu cita de hoy a las ${(cita.hora_cita || '').slice(0, 5)} hrs para ver el ${cita.auto_interes || 'auto que te interesa'}. ¡Te esperamos! 🚗`;
return [{ json: { citaId: cita.id, telefono: cita.telefono, instanceName: instancia.instance_name || null, apiKey: instancia.api_key || null, mensaje } }];

const lead = $('Buscar Leads Sin Agendar').item.json;
const historial = ($json && $json[0]) || null;
if (!historial) return [];
const ahora = new Date();
const ultimoMensaje = new Date(historial.created_at);
