return [{json:{ profileExists: status === 200 && payload.success !== false && !!payload.profile,
  lookupValid: status === 404 || (status === 200 && !!payload.profile), errorCode:'UPLOAD_POST_LOOKUP_FAILED' }}];

const status = Number($json.statusCode || 0);
const result = $json.body || $json;
const text = JSON.stringify(result.error || result.code || result.message || '');
const existing = status === 409;
const created = status >= 200 && status < 300 && result.success === true;
