const body = $('Webhook Publicar Redes1').item.json.body || {};
const platforms = Array.isArray(body.platforms) ? [...new Set(body.platforms)] : [];
const urls = Array.isArray(body.image_urls) && body.image_urls.length ? body.image_urls : [body.image_url];
const carId = String(body.car?.id || '');
const requestId = String(body.request_id || '');
const valid = /^\d{1,19}$/.test(carId) && /^[a-zA-Z0-9_-]{16,128}$/.test(requestId) &&
 platforms.length > 0 && platforms.every(p=>['facebook','instagram'].includes(p)) &&
 typeof body.copy === 'string' && body.copy.trim().length > 0 && body.copy.length <= 2200 &&
 urls.length > 0 && urls.length <= 10 && urls.every(url=>typeof url==='string' && /^https:\/\/[^\s]+$/.test(url));
const copy = valid ? body.copy.trim() : '';
const fields = valid ? [
  ['user', $('Normalizar Verificación Token2').item.json.loteId],
  ['title', copy], ['async_upload', 'true'], ['request_id', requestId],
  ...platforms.map(value=>['platform[]',value]), ...urls.map(value=>['photos[]',value])
] : [];
let boundary = 'velodrive_' + requestId;
while (fields.some(([,value])=>String(value).includes(boundary))) boundary += '_';
const multipartBody = fields.map(([name,value])=>'--'+boundary+'\r\nContent-Disposition: form-data; name="'+name+'"\r\n\r\n'+value+'\r\n').join('')+'--'+boundary+'--\r\n';
return [{json:{valid,carId,requestId,platforms,urls,copy,boundary,multipartBody,httpStatus:400,error:'Selecciona Facebook o Instagram, una unidad, de 1 a 10 fotos y un texto de hasta 2200 caracteres.'}}];

const result = $json.body || $json;
const requestId = $('Validar Datos de Publicación').item.json.requestId;
const accepted = Number($json.statusCode || 200) < 400 && result.success === true && result.request_id === requestId;
return [{json:{accepted,request_id:requestId,httpStatus:502,error:'No se confirmó el envío. Verifica el estado antes de reintentar; se conservará el identificador para evitar duplicados.'}}];

const b = $('Webhook Verificar Publicación1').item.json.body || {};
const valid = /^\d{1,19}$/.test(String(b.car_id||'')) && /^[a-zA-Z0-9_-]{16,128}$/.test(String(b.request_id||'')) && b.plataforma === 'meta';
return [{json:{valid,carId:String(b.car_id||''),requestId:String(b.request_id||''),httpStatus:400,error:'La consulta de publicación no es válida.'}}];

const channel=$json; const auth=$('Normalizar Verificación Token8').first().json;
const body=$('Webhook QR WhatsApp').first().json.body||{};
return [{json:{loteId:auth.loteId,instance:channel.instance_name||('instancia_'+auth.loteId),accion:body.accion==='estado'?'estado':'conectar'}}];

const status=Number($json.statusCode||0); const state=$json.body?.instance?.state;
const exists=status===200&&['open','close','connecting'].includes(state);
return [{json:{valid:exists||status===404,exists,connected:state==='open',state:state||'unknown',httpStatus:502,error:'No se pudo consultar Evolution. Intenta de nuevo.'}}];

const ctx=$('Preparar conexión QR').first().json;
const rows=Array.isArray($json.body)?$json.body:[];
const instance=rows.find(row=>row.name===ctx.instance);
const valid=Number($json.statusCode)===200&&!!instance&&typeof instance.token==='string'&&instance.token.length>0;
return [{json:{valid,lote_id:ctx.loteId,instance_name:ctx.instance,api_key:valid?instance.token:null,phone_number:valid?String(instance.ownerJid||instance.number||'').split('@')[0]:null,connected:instance?.connectionStatus==='open',httpStatus:502,error:'No se pudo confirmar la instancia del lote. Intenta de nuevo.'}}];

const b=$json.body||{};
const expected='https://n8n-production-97a4.up.railway.app/webhook/whatsapp-lotes?secret='+encodeURIComponent($env.WEBHOOK_SECRET||'');
const valid=Number($json.statusCode)>=200&&Number($json.statusCode)<300&&!!$env.WEBHOOK_SECRET&&b.enabled===true&&b.url===expected&&Array.isArray(b.events)&&b.events.includes('MESSAGES_UPSERT');
return [{json:{valid,httpStatus:502,error:'No se pudo preparar la recepción de mensajes. Intenta de nuevo.'}}];

const status=Number($json.statusCode||0); const b=$json.body||{};
const conflict=status===403&&JSON.stringify(b).toLowerCase().includes('already in use');
return [{json:{valid:(status>=200&&status<300)||conflict,httpStatus:502,error:'No se pudo crear la instancia de WhatsApp. Intenta de nuevo.'}}];

const b=$json.body||{};const raw=b.base64||b.qrcode?.base64;
const qr=typeof raw==='string'&&/^data:image\/(png|jpeg);base64,[A-Za-z0-9+/=]+$/.test(raw)?raw:null;
return [{json:{valid:Number($json.statusCode)===200,conectado:false,qr_base64:qr,expires_in:45,pending:!qr,httpStatus:502,error:'Evolution no pudo generar el QR. Intenta de nuevo.'}}];
